using System;using System.Threading;using System.Diagnostics;using System.Collections.Generic;
public class QueueConcurrencyHarness {
 public static void Main(){int failures=0,max=0;var samples=new List<double>();var p=Process.GetCurrentProcess();var cpu=p.TotalProcessorTime;for(int r=0;r<1000;r++){var q=new DeskPagesCommandQueue();var go=new ManualResetEvent(false);Thread[] ts=new Thread[16];for(int i=0;i<ts.Length;i++){ts[i]=new Thread(()=>{go.WaitOne();var s=Stopwatch.StartNew();q.Enqueue(1,false,0);lock(samples)samples.Add(s.Elapsed.TotalMilliseconds);});ts[i].Start();}go.Set();foreach(var t in ts)t.Join();int n=0;DeskPagesInputCommand c;while(q.TryDequeue(out c))n++;if(n>3)failures++;max=Math.Max(max,n);go.Dispose();}if(failures!=0)throw new Exception("Command queue exceeded its capacity");samples.Sort();double sum=0;foreach(double x in samples)sum+=x;Console.WriteLine("Rounds=1000; Threads=16; CapacityFailures="+failures+"; MaxDepth="+max+"; MeanMs="+sum/samples.Count+"; P95Ms="+samples[(int)(samples.Count*.95)]+"; P99Ms="+samples[(int)(samples.Count*.99)]+"; PrivateBytes="+p.PrivateMemorySize64+"; CpuMs="+(p.TotalProcessorTime-cpu).TotalMilliseconds);}
}